def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Check if in given list of numbers, are any two numbers closer to each other than
    given threshold.

    :param numbers: List of numbers to check
    :param threshold: Threshold value
    :return: True if any two numbers are closer to each other than threshold, False otherwise
    """
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate groups of nested parentheses in a string.

    :param paren_string: A string containing multiple groups of nested parentheses.
    :return: A list of strings, where each string is a group of balanced parentheses.
    """
    result = []
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            top = stack.pop()
            if top == '(':
                result.append('()')
            else:
                result[-1] += ')'
    return result

